() => {
  const el = document.querySelector('[aria-label="Incident report content"]') || document.activeElement;
  function describe(node) {
    if (!node) return null;
    return {
      tag: node.tagName,
      role: node.getAttribute && node.getAttribute('role'),
      contentEditable: node.contentEditable,
      className: node.className,
      isInput: node.tagName === 'TEXTAREA' || node.tagName === 'INPUT',
    };
  }
  const found = document.querySelectorAll('textarea, input, [contenteditable="true"]');
  return {
    target: describe(el),
    allEditableLike: Array.from(found).map(describe),
  };
}

