  const el = document.querySelector('[aria-label="Incident report content"]');
  let cur = el;
  const chain = [];
  while (cur) {
    chain.push({tag: cur.tagName, contentEditableAttr: cur.getAttribute && cur.getAttribute('contenteditable'), id: cur.id, cls: cur.className});
    cur = cur.parentElement;
    if (chain.length > 8) break;
  }
  return { outerHTML: el.outerHTML.slice(0, 500), chain };
}

